data class Reply(val status: Int, val body: String)

// POST /payments: the Idempotency-Key header and the raw JSON body
fun charge(idemKey: String, requestJson: String): Reply {
    val hash = sha256(requestJson)                            // same body, same hash
    return when (val begin = store.begin(idemKey, hash)) {
        is Begin.Replay -> Reply(200, begin.response)
        Begin.InProgress -> Reply(409, """{"error":"in progress"}""")
        Begin.Mismatch -> Reply(422, """{"error":"key reused"}""")
        is Begin.Started -> {
            val response = issuer.authorize(requestJson)      // the side effect, once per key
            store.complete(idemKey, hash, begin.token, response)
            Reply(200, response)
        }
    }
}

